"""Cardinal-arithmetic evaluator: cardinality is blind to dimension."""
from __future__ import annotations
from dataclasses import dataclass


@dataclass(frozen=True)
class Cardinal:
    name: str
    def __repr__(self) -> str:
        return self.name


ALEPH0 = Cardinal("aleph_0")
CONTINUUM = Cardinal("c")  # c = 2 ** aleph_0


def continuum_pow_finite(n: int) -> Cardinal:
    """c ** n = c for n >= 1, by the squeeze c = c^1 <= c^n <= c^aleph_0 = c."""
    if n < 1:
        raise ValueError("need n >= 1")
    return CONTINUUM


def continuum_pow_aleph0() -> Cardinal:
    """c ** aleph_0 = 2 ** (aleph_0 * aleph_0) = 2 ** aleph_0 = c."""
    return CONTINUUM


def card_hilbert_cube() -> Cardinal:
    return continuum_pow_aleph0()


def card_euclidean(n: int) -> Cardinal:
    return continuum_pow_finite(n)


def main() -> None:
    q = card_hilbert_cube()
    print(f"|Q| = c^aleph_0 = {q}")
    for n in (1, 2, 3, 10, 1000):
        print(f"|R^{n}| = c^{n} = {card_euclidean(n)}  equals |Q|? "
              f"{card_euclidean(n) == q}")
    print("Under CH, c = aleph_1, so |Q| = aleph_1.")


if __name__ == "__main__":
    main()

"""Self-similarity: Q ~= Q x [0,1] and Q ~= Q x Q via coordinate shuffles."""
from __future__ import annotations
from fractions import Fraction
from typing import Callable, Tuple

HilbertPoint = Callable[[int], Fraction]


def absorb(p: HilbertPoint) -> Tuple[HilbertPoint, Fraction]:
    """Q -> Q x [0,1]: coordinate 0 becomes the interval value; the rest shift."""
    return (lambda j: p(j + 1)), p(0)


def unabsorb(q_part: HilbertPoint, extra: Fraction) -> HilbertPoint:
    """Q x [0,1] -> Q: glue the extra value back as coordinate 0."""
    return lambda k: extra if k == 0 else q_part(k - 1)


def self_square(p: HilbertPoint) -> Tuple[HilbertPoint, HilbertPoint]:
    """Q -> Q x Q: even coordinates to the first copy, odd to the second."""
    return (lambda j: p(2 * j)), (lambda j: p(2 * j + 1))


def reinterleave(left: HilbertPoint, right: HilbertPoint) -> HilbertPoint:
    return lambda k: left(k // 2) if k % 2 == 0 else right(k // 2)


def main() -> None:
    p: HilbertPoint = lambda k: Fraction(1, k + 2)
    depth = 8
    original = [p(k) for k in range(depth)]

    q_part, extra = absorb(p)
    back = unabsorb(q_part, extra)
    print("Q ~= Q x [0,1] round-trip identical?",
          [back(k) for k in range(depth)] == original)

    left, right = self_square(p)
    reb = reinterleave(left, right)
    print("Q ~= Q x Q round-trip identical?",
          [reb(k) for k in range(depth)] == original)


if __name__ == "__main__":
    main()

