from __future__ import annotations
from typing import Literal, Union

Level = Union[int, Literal["aleph_0"]]


def reduce_power(base_exp: Level, outer_exp: Level) -> str:
    """Reduce (2 ** base_exp) ** outer_exp to a canonical cardinal name.

    Uses:  aleph_0 * aleph_0 = aleph_0,  n * aleph_0 = aleph_0 (n>=1),
    and 2 ** finite = finite power of 2 (still < aleph_0 only if base finite).
    Here base is always aleph_0 (we track cardinals of the form 2**aleph_0 = c).
    """
    def is_inf(x: Level) -> bool:
        return x == "aleph_0"

    # product of the two exponents in the ladder {finite, aleph_0}
    if is_inf(base_exp) or is_inf(outer_exp):
        product: Level = "aleph_0"
    else:
        product = base_exp * outer_exp  # finite * finite
    if product == "aleph_0":
        return "c"          # 2 ** aleph_0
    return f"2**{product}"   # a finite cardinal


def card_hilbert_cube() -> str:
    # |Q| = (2**aleph_0) ** aleph_0
    return reduce_power("aleph_0", "aleph_0")


def card_euclidean(n: int) -> str:
    # |R^n| = (2**aleph_0) ** n
    return reduce_power("aleph_0", n)

from __future__ import annotations
from fractions import Fraction
from typing import Callable, List, Sequence

HilbertPoint = Callable[[int], Fraction]


def embed_cube(n: int, x: Sequence[Fraction]) -> HilbertPoint:
    """s_n: pad an n-cube point with zeros to a point of the Hilbert cube."""
    if len(x) != n:
        raise ValueError("dimension mismatch")
    return lambda k: x[k] if k < n else Fraction(0)


def truncate(n: int, p: HilbertPoint) -> List[Fraction]:
    """p_n: the continuous left inverse; keep the first n coordinates."""
    return [p(i) for i in range(n)]


def is_embedding_witness(n: int, x: Sequence[Fraction]) -> bool:
    """Certify p_n(s_n(x)) = x, the left-inverse identity behind the embedding."""
    return truncate(n, embed_cube(n, x)) == list(x)

