from __future__ import annotations
from fractions import Fraction
from typing import Callable, Tuple

HilbertPoint = Callable[[int], Fraction]


def peel_forward(k: int) -> Tuple[str, int]:
    """tau: N -> N + {*}. Slot 0 -> extra '*'; k>=1 -> k-1 in the main copy."""
    return ("star", 0) if k == 0 else ("nat", k - 1)


def peel_backward(tag: str, j: int) -> int:
    """Inverse of peel_forward."""
    return 0 if tag == "star" else j + 1


def absorb_coordinate(p: HilbertPoint) -> Tuple[HilbertPoint, Fraction]:
    """Homeomorphism Q -> Q x [0,1] realized by the coordinate shift tau."""
    return (lambda j: p(peel_backward("nat", j))), p(0)


def unabsorb_coordinate(q: HilbertPoint, extra: Fraction) -> HilbertPoint:
    """Inverse homeomorphism Q x [0,1] -> Q."""
    def p(k: int) -> Fraction:
        tag, j = peel_forward(k)
        return extra if tag == "star" else q(j)
    return p
